function rsi2(closes) {
  let g = 0, l = 0;
  for (let i = closes.length - 2; i < closes.length; i++) {
    const d = closes[i] - closes[i - 1];
    if (d > 0) g += d; else l -= d;
  }
  if (l === 0) return 100;
  return 100 - 100 / (1 + (g / 2) / (l / 2));
